WITH exploded AS (SELECT id, service, status_code, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, attr_value) SELECT id, service, status_code, key, attr_value, ROUND(status_code / SUM(status_code) OVER (PARTITION BY key), 4) AS status_code_share, MIN(status_code) OVER (PARTITION BY service) AS service_min_status_code, ROUND(status_code / SUM(status_code) OVER (PARTITION BY key), 4) AS status_code_share_2, CUME_DIST() OVER (PARTITION BY key ORDER BY status_code ASC) AS status_code_cume_dist FROM exploded;
